import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
process.chdir('/Users/tal/dev/melian-worktrees/quiet-run-details');
const path = process.argv[2];
const inventory = JSON.parse(readFileSync(path, 'utf8'));
for (const [index, mutant] of inventory.mutants.entries()) {
 if (mutant.result !== undefined) continue;
 const original = readFileSync(mutant.file, 'utf8');
 const offset = (line, column) => original.split('\n').slice(0, line - 1).reduce((sum, text) => sum + text.length + 1, 0) + column;
 const testFiles = mutant.tests ?? ['packages/pipeline/test/run-check-outcomes.test.ts'];
 const start = offset(mutant.line, mutant.column), end = offset(mutant.endLine, mutant.endColumn);
 let result;
 try {
  writeFileSync(mutant.file, original.slice(0, start) + mutant.replacement + original.slice(end));
  result = spawnSync('npx', ['vitest', '--run', ...testFiles], { encoding: 'utf8', timeout: 60000 });
 } finally { writeFileSync(mutant.file, original); }
 const log = `${process.env.TMPDIR}/quiet-run-details-mutant-${inventory.pass}-${index}.log`;
 writeFileSync(log, (result.stdout ?? '') + (result.stderr ?? ''));
 mutant.result = result.status === 0 ? 'survived' : result.status === null ? 'timeout' : 'killed';
 mutant.exitCode = result.status;
 mutant.log = log;
 mutant.claim ??= 'new-test';
 mutant.evidence ??= testFiles.join(', ');
 mutant.survivorClasses ??= ['dropped-value'];
 writeFileSync(path, JSON.stringify(inventory, null, 2) + '\n');
 console.log(`${index + 1}/${inventory.total} ${mutant.result} ${mutant.file}:${mutant.line} ${mutant.mutatorName}`);
}

